#!/usr/bin/env node
// Builds the UI with Vite and turns dist/ui into src/server/assets.generated.ts, which the server serves and
// `bun build --compile` embeds. The generated file is gitignored.
//   node scripts/build-ui.mjs                 build + generate
//   node scripts/build-ui.mjs --stub-if-missing   only write an empty module if none exists (for typecheck)
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, extname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const generated = join(root, 'src', 'server', 'assets.generated.ts');
const header = '// GENERATED by scripts/build-ui.mjs. Do not edit; not committed.\n';

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.wasm': 'application/wasm',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.woff2': 'font/woff2',
  '.json': 'application/json; charset=utf-8',
};

export function renderModule(files) {
  const body = files.map(([url, type, data]) => `  ${JSON.stringify(url)}: { type: ${JSON.stringify(type)}, data: ${JSON.stringify(data)} },`).join('\n');
  return `${header}export const ASSETS: Record<string, { type: string; data: string }> = {\n${body}\n};\n`;
}

function walk(dir) {
  return readdirSync(dir).flatMap((n) => (statSync(join(dir, n)).isDirectory() ? walk(join(dir, n)) : [join(dir, n)]));
}

if (process.argv.includes('--stub-if-missing')) {
  if (!existsSync(generated)) {
    mkdirSync(dirname(generated), { recursive: true });
    writeFileSync(generated, renderModule([]));
  }
} else {
  const { build } = await import('vite');
  await build({ configFile: join(root, 'vite.config.ts'), logLevel: 'warn' });
  const out = join(root, 'dist', 'ui');
  const files = walk(out).map((f) => {
    const url = '/' + relative(out, f).split('\\').join('/');
    const type = TYPES[extname(f)];
    if (!type) throw new Error(`no content type for ${url}`);
    return [url === '/index.html' ? '/' : url, type, readFileSync(f).toString('base64')];
  });
  writeFileSync(generated, renderModule(files));
  console.log(`embedded ${files.length} UI files`);
}
